INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-alfabeto-humano', 'El Alfabeto Humano', 'Dinámica de composición espacial y agilidad postural donde las patrullas se acuestan en el pasto para formar letras gigantes con sus cuerpos.', '<h2>📜 Descripción de El Alfabeto Humano</h2>
<p><b>El Alfabeto Humano</b> es una dinámica scout de motricidad adaptativa, esquema corporal y coordinación de patrulla. En esta actividad, los participantes se organizan por equipos sobre el césped de campamento o gimnasio. El dirigente proclama en voz alta una letra del alfabeto (ej. <i>''¡Letra A!''</i> o <i>''¡Letra M!''</i>) y las patrullas disponen de 15 segundos para acostarse e interconectar sus cuerpos, brazos y piernas formando el carácter caligráfico gigante. Los dirigentes evalúan la nitidez visual y la proporción de la figura desde una posición elevada.</p>
<p>Esta dinámica ejercita la creatividad tridimensional, la agilidad mental y la cohesión corporal en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Alfabeto Humano?</h2>
<p>Para llevar a cabo la dinámica con ritmo y orden, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Dispersión Inicial:</b> Los participantes caminan o trotan por la cancha al compás de palmadas.</li>
  <li><b>La Proclamación de la Letra:</b> El dirigente detiene la marcha y grita en voz alta el carácter designado (ej. <i>''¡Formen la letra K!''</i>).</li>
  <li><b>Tendido y Acoplamiento:</b> Los miembros de la patrulla se tiran de inmediato al pasto, alineando sus troncos y extremidades para dar forma a los trazos de la letra.</li>
  <li><b>Verificación y Fotografía:</b> Transcurridos los 15 segundos, los equipos sostienen la postura en silencio mientras el jurado valida la legibilidad de la letra desde arriba.</li>
  <li><b>Construcción de Palabras:</b> En rondas avanzadas, varias patrullas cooperan simultáneamente para formar una palabra scout completa (ej. <i>''PAZ''</i> o <i>''SOL''</i>).</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Alfabeto Humano</h2>
<p>La actividad valora la velocidad de respuesta y la claridad anatómica en el Tally:</p>
<ul>
  <li><b>Mayor Legibilidad Caligráfica:</b> Otorgar 5 puntos a la patrulla o seisena que logre la letra más proporcional y clara.</li>
  <li><b>Rapidez de Construcción:</b> Otorgar 3 puntos al equipo que complete la figura antes de los 15 segundos.</li>
  <li><b>Espíritu de Cooperación:</b> Otorgar 3 puntos a la unidad que integre activamente a todos sus miembros en el trazo.</li>
</ul>', '/uploads/el-alfabeto-humano.webp', 'publicado', '{"areas": ["creatividad", "corporalidad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Exterior", "Campo Abierto", "Interior", "Sala"], "materiales": ["Sin Materiales"], "objetivos": ["Incrementar continuamente sus conocimientos mediante la autoformación", "Conocer las capacidades corporales y motricidad", "Estimular la agilidad mental y composición espacial", "Favorecer la cooperación en el equipo"], "justificacion_areas": "El Alfabeto Humano potencia la creatividad al incentivar la resolución analítica inmediata de formas tipográficas mediante la distribución de volúmenes en el espacio. Desarrolla la corporalidad al afianzar el esquema corporal, el equilibrio supino y la flexibilidad. Fortalece la sociabilidad al consolidar la lealtad y el acoplamiento armónico entre los integrantes de la patrulla.", "variaciones": "<b>Símbolos y Números Scouts:</b> Formar números de clave morse, la Flor de Lis o la Paloma de la Paz.<br><b>Alfabeto en Sombras:</b> Proyectar las siluetas corporales contra una pared blanca iluminada por linternas de campamento.<br><b>Alfabeto Silencioso:</b> Indicar las letras exclusivamente mediante tarjetas visuales sin pronunciar ningún sonido.", "recomendaciones": "Inspeccionar el terreno antes de la actividad para asegurar que el pasto esté seco y libre de piedras filosas o espinas. Promover el uso del pañolín scout sobre el cuello para evitar rozaduras con el césped.", "objetivos_educativos": [{"id": "0fdac5b5-f76d-4141-9dba-397ca49a5fcc", "area": "Creatividad", "unidad": "Manada", "texto": "Participo en actividades donde puedo conocer algo nuevo.", "como_se_cumple": "Descubriendo nuevas formas de representar caracteres tipográficos con el cuerpo."}, {"id": "a7539c03-7e17-4e1b-8e3b-081c8a8161cc", "area": "Creatividad", "unidad": "Manada", "texto": "Investigo y descubro cómo funcionan las cosas.", "como_se_cumple": "Investigando con la seisena la mejor distribución de extremidades para la letra."}, {"id": "1b5e42cb-c832-4c3a-8ed5-a3050b6e2285", "area": "Creatividad", "unidad": "Compañía", "texto": "Me intereso por conocer más sobre lo que pasa a mi alrededor.", "como_se_cumple": "Ampliando mi capacidad analítica espacial al componer símbolos colectivos."}, {"id": "aacee532-b682-4d8e-8c5d-d6e9396162a4", "area": "Creatividad", "unidad": "Compañía", "texto": "Me preocupo por saber cada vez más sobre los temas que me interesan.", "como_se_cumple": "Perfeccionando con rigurosidad sistemática la simetría y proporciones de las letras."}, {"id": "a93b3a5c-a023-4e0c-815d-c77c6700dd89", "area": "Creatividad", "unidad": "Tropa", "texto": "Me intereso por conocer más sobre lo que pasa a mi alrededor.", "como_se_cumple": "Fomentando el aprendizaje por la acción y la construcción tridimensional en equipo."}, {"id": "071e6f2d-cb33-48c7-a385-4c63d873b254", "area": "Creatividad", "unidad": "Tropa", "texto": "Me preocupo por saber cada vez más sobre los temas que me interesan.", "como_se_cumple": "Liderando con creatividad la resolución de tipografías complejas en la patrulla."}, {"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "unidad": "Manada", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Ejercitando el control tónico y la flexibilidad en el suelo de campamento."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Manada", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Afinando el esquema corporal al acoplar brazos y piernas con los compañeros."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "unidad": "Compañía", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Respetando los límites de tiempo y las reglas de inmovilidad en el pasto."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Exigiendo precisión motriz en los tendidos y levantamientos rápidos."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "unidad": "Tropa", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Desarrollando la motricidad rítmica adaptativa en ejercicios de patrulla."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Perfeccionando el control kinesiológico en posturas colectivas exigentes."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando con lealtad el espacio de cada lobato en el trazo de la letra."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Acatando las decisiones del jefe de seisena para la posición final."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Promoviendo el respeto por el espacio corporal de las compañeras de equipo."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Favoreciendo la integración armónica y sin exclusiones dentro de la patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el espíritu fraterno y el trabajo coordinado en la Tropa."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Asumiendo el liderazgo y el cumplimiento ético de las reglas del juego."}]}'::jsonb, NOW(), NOW(), NULL, NULL
